-- Catalogul Romcrete: pompe Graco și accesorii.
--
-- 103 pompe + 55 familii de accesorii = 155 poziții
-- (două pompe erau listate în câte două categorii; sunt unite într-o singură poziție).
-- 100 poziții au materialele compatibile, care alimentează sugestiile din teren.
--
-- Prețurile din magazin sunt cu TVA; unit_price e prețul fără TVA, folosit pe ofertă,
-- iar price_with_vat păstrează prețul din magazin pentru verificare.
--
-- Migrația ȘTERGE catalogul firmei și îl reconstruiește. Pe o bază fără nicio
-- organizație nu face nimic — se aplică din nou când firma există, printr-o
-- migrație nouă cu același conținut.
--
-- La actualizarea prețurilor NU se modifică acest fișier: se generează o migrație
-- nouă, datată, ca istoricul să rămână întreg.

do $$
declare
  v_org   uuid;
  v_count int;
begin
  select count(*) into v_count from public.organizations;

  if v_count = 0 then
    raise notice 'Nicio organizație încă — catalogul se încarcă după ce firma e creată.';
    return;
  end if;

  if v_count > 1 then
    raise exception 'Am găsit % organizații. Alege manual org_id înainte de import.', v_count;
  end if;

  select id into v_org from public.organizations;

  delete from public.catalog_items where org_id = v_org;

